namespace {
using namespace dft::memory;size_t checks=0;
void need(bool b,const char *why){++checks;if(!b)throw std::runtime_error(why);}
MemoryResourceUsageRequest request() {
    MemoryResourceUsageRequest r;auto lib=loadMemoryLibrary(std::filesystem::path(DFT_MEMORY_UNITS_DIR)/"memory-test-schedule-library.json");need(bool(lib),"library");
    auto &t=r.test.schedule.test;t.investigation.scope="schedule_top";t.investigation.recursive=true;t.investigation.mapping.models=lib->models;t.planning.profiles=lib->testProfiles;t.planning.policy.maxParallelMemories=2;
    for(const auto *n:{"a0","a1","a2","a3","b0","b1","c0","d0"})t.planning.assignments.push_back({std::string("schedule_top.")+n,std::string(1,n[0]),""});
    r.test.schedule.scheduling.policy={4,1000000};r.test.schedule.scheduling.resources={{"all",4,{"a","b","c","d"}}};auto &resource=r.test.schedule.scheduling.resources[0];resource.maxUnits=4;resource.domainUnits={{"a",3},{"b",2}};
    for(const auto *q:{"a","b","c","d"}){r.test.timing.clocks.push_back({q,1000});}r.test.timing.policy.waveOverheadPicoseconds=7;return r;
}
std::vector<std::vector<size_t>> members(const MemoryTestSchedule &s){std::vector<std::vector<size_t>> out;for(const auto &w:s.waves){std::vector<size_t> row;for(const auto &e:w.entries)row.push_back(e.controller);out.push_back(row);}return out;}
MemoryTestConfiguration config(const MemoryResourceUsageRequest &r){return {r.test.schedule.test.planning,r.test.schedule.rules,r.test.schedule.scheduling,r.test.timing};}
std::string json(const MemoryResourceUsageComparison &r){hier::protocol::JsonWriter w;writeMemoryResourceUsageComparison(w,r);return w.str();}
}
int main()try {
    hier::model::OpenOptions o;o.tops={"schedule_top"};o.files={(std::filesystem::path(DFT_MEMORY_UNITS_DIR)/"memory-test-schedule.sv").string()};auto design=hier::Design::open(o);need(design&&design.value()->diagnostics(10).errorCount==0,"open");auto &d=*design.value();auto r=request();auto got=inspectMemoryResourceUsage(d,r);need(got&&got->usage.complete,"complete");
    need(members(got->source.source.schedule)==std::vector<std::vector<size_t>>{{0,2},{0,3},{1}},"weighted first fit, no per-memory multiplication");const auto &row=got->usage.rows[0];need(row.peakUnits==4&&row.peakControllers==2&&row.peakPowerMicrowatts==300000&&row.occupiedPicoseconds==48021,"independent peaks");need(got->source.source.schedule.work==16&&got->usage.work==10&&got->usage.processedWaves==3,"unchanged per-visit work");
    auto plain=r;plain.test.schedule.scheduling.resources[0].domainUnits.clear();plain.test.schedule.scheduling.resources[0].maxUnits=0;auto old=inspectMemoryResourceUsage(d,plain);need(old&&old->usage.complete&&!old->usage.rows[0].peakUnits&&old->usage.rows[0].peakControllers==4&&old->usage.rows[0].occupiedPicoseconds==32014,"implicit unit compatibility");
    auto q=r;q.test.schedule.scheduling.resources[0].maxUnits=0;auto unlimited=inspectMemoryResourceUsage(d,q);need(unlimited&&unlimited->usage.rows[0].peakUnits==7&&members(unlimited->source.source.schedule)==members(old->source.source.schedule),"unlimited units still observed");
    q=plain;q.test.schedule.scheduling.resources[0].maxUnits=2;auto two=inspectMemoryResourceUsage(d,q);need(two&&two->usage.rows[0].peakUnits==2&&members(two->source.source.schedule)==std::vector<std::vector<size_t>>{{0,1},{0,2},{3}},"default demands under unit ceiling");
    q=r;q.test.schedule.scheduling.resources[0].maxParallelControllers=1;auto count=inspectMemoryResourceUsage(d,q);need(count&&count->usage.processedWaves==5&&count->usage.rows[0].peakUnits==3&&count->usage.rows[0].peakControllers==1,"count cap independent");
    q=r;q.test.schedule.test.planning.policy.maxMemoriesPerController=2;q.test.schedule.scheduling.resources[0].maxUnits=6;auto same=inspectMemoryResourceUsage(d,q);need(same&&same->usage.rows[0].peakUnits==6&&same->source.source.schedule.waves[0].entries.size()==2,"same domain controllers reserve separately");
    q=r;q.test.schedule.scheduling.resources[0].domainUnits[0].units=5;q.test.schedule.scheduling.dependencies={{"a","b"}};auto block=inspectMemoryResourceUsage(d,q);need(block&&!block->usage.complete&&block->source.source.schedule.controllers[0].reason=="resource_units_exceeded"&&block->source.source.schedule.controllers[0].resource==0&&block->source.source.schedule.controllers[1].reason=="dependency_blocked","unit block and dependency propagation");
    q.test.schedule.scheduling.resources[0].maxPowerMicrowatts=100000;auto priority=inspectMemoryResourceUsage(d,q);need(priority&&priority->source.source.schedule.controllers[0].reason=="resource_power_exceeded","power diagnosis before unit diagnosis");
    q=r;q.test.schedule.scheduling.resources={{"early",1,{"a","b"}},{"late",4,{"a"}}};q.test.schedule.scheduling.resources[1].maxUnits=1;q.test.schedule.scheduling.resources[1].domainUnits={{"a",2}};auto late=inspectMemoryResourceUsage(d,q);need(late&&late->source.source.schedule.controllers[0].resource==1&&members(late->source.source.schedule)==std::vector<std::vector<size_t>>{{1,2,3}}&&late->usage.rows[0].peakControllers==1&&late->usage.rows[1].peakUnits==0,"late rejection does not reserve earlier resource");
    q=r;q.test.schedule.scheduling.resources.push_back({"overlap",4,{"a","c"}});q.test.schedule.scheduling.resources[1].domainUnits={{"a",7},{"c",9}};auto overlap=inspectMemoryResourceUsage(d,q);need(overlap&&overlap->usage.rows[1].peakUnits==16&&overlap->usage.rows[0].peakUnits==4,"overlap own demand and whole-wave membership");
    for(uint64_t cap=1;cap<=10;++cap){q=r;q.limits.maxWork=cap;auto x=inspectMemoryResourceUsage(d,q);const uint64_t waves=cap<4?0:cap<8?1:cap<10?2:3;need(x&&x->usage.work==cap&&x->usage.processedWaves==waves&&x->usage.rows[0].peakUnits==(waves?4:0)&&x->usage.rows[0].occupiedPicoseconds==waves*16007&&x->usage.complete==(cap==10),"usage cutoff commits units and uses atomically");}
    for(uint64_t cap=1;cap<=16;++cap){q=r;q.test.schedule.scheduling.limits.maxWork=cap;auto x=inspectMemoryResourceUsage(d,q);const uint64_t waves=cap<8?0:cap<14?1:cap<16?2:3;need(x&&x->source.source.schedule.work==cap&&x->source.source.schedule.waves.size()==waves&&x->usage.rows[0].peakUnits==(waves?4:0)&&x->usage.complete==(cap==16),"scheduler cutoff never publishes candidate units");}
    q=r;q.limits.maxUses=1;auto uses=inspectMemoryResourceUsage(d,q);need(uses&&uses->usage.processedWaves==1&&uses->usage.rows[0].peakUnits==4,"uses budget prefix");
    q=r;auto &huge=q.test.schedule.scheduling.resources[0];huge.maxUnits=0;huge.domainUnits={{"a",1000000000000ULL},{"b",1000000000000ULL},{"c",1000000000000ULL},{"d",1000000000000ULL}};auto big=inspectMemoryResourceUsage(d,q);need(big&&big->usage.rows[0].peakUnits==4000000000000ULL,"sum beyond per-demand bound remains exact");
    MemoryResourceUsageComparisonRequest compare;compare.tests.investigation=r.test.schedule.test.investigation;compare.tests.configurations={{"implicit",config(plain)},{"weighted",config(r)},{"unlimited",config(q)}};auto cmp=compareMemoryResourceUsage(d,compare);need(cmp&&cmp->complete&&!cmp->rows[0].cells[0].delta->peakUnits&&cmp->rows[0].cells[1].delta->peakUnits==0&&cmp->rows[0].cells[2].delta->peakUnits==3999999999996LL,"comparison implicit baseline and exact signed units");
    std::swap(compare.tests.configurations[0],compare.tests.configurations[2]);auto negative=compareMemoryResourceUsage(d,compare);need(negative&&negative->rows[0].cells[0].delta->peakUnits==0&&negative->rows[0].cells[2].delta->peakUnits==-3999999999996LL,"weighted self zero and negative delta");compare.limits.maxWork=1;auto partial=compareMemoryResourceUsage(d,compare);need(partial&&!partial->rows[0].cells[1].delta,"partial no unit delta");
    for(int kind=0;kind<7;++kind){q=r;q.test.schedule.test.investigation.scope="missing";auto &rs=q.test.schedule.scheduling.resources[0];if(kind==0)rs.maxUnits=1000000000001ULL;if(kind==1)rs.domainUnits[0].units=0;if(kind==2)rs.domainUnits[0].units=1000000000001ULL;if(kind==3)rs.domainUnits[0].clockDomain="absent";if(kind==4)rs.domainUnits.push_back({"a",1});if(kind==5)rs.domainUnits[0].clockDomain=std::string("a\0",2);if(kind==6)rs.domainUnits[0].clockDomain=std::string(1,char(0xff));auto bad=inspectMemoryResourceUsage(d,q);need(!bad&&bad.error().code==hier::ErrorCode::BadRequest,"invalid unit declaration before query");}
    std::stop_source stop;stop.request_stop();need(inspectMemoryResourceUsage(d,q,stop.get_token()).error().code==hier::ErrorCode::Cancelled,"cancel before invalid request");auto expired=detail::inspectMemoryResourceUsageWithDeadline(d,r,std::chrono::steady_clock::time_point::min());need(expired&&expired->usage.rows[0].peakUnits==0&&!expired->usage.work&&!expired->usage.processedWaves&&expired->usage.stop->reason=="budget_time","expired index only empty rows");auto scheduleExpired=detail::scheduleMemoryTestsWithDeadline(d,r.test.schedule,std::chrono::steady_clock::time_point::min());need(scheduleExpired&&scheduleExpired->schedule.waves.empty()&&!scheduleExpired->schedule.work,"expired scheduler index");
    const auto bytes=json(*cmp);r={};compare={};design.value().reset();need(json(*cmp)==bytes,"owning unit output");std::cout<<checks<<" resource unit assertions passed\n";return 0;
}catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}
